import { bigint, numeric, text, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Column factories, so that every table in this schema makes the same three
 * decisions the same way: how a row is identified, how money is stored, and how
 * time is recorded.
 *
 * These are factories rather than shared objects on purpose — a Drizzle column
 * builder carries per-table state, so handing the same instance to two tables
 * corrupts both.
 */

/** UUID v4, generated by Postgres. Chosen over a serial because ids travel to the client. */
export const primaryKeyId = () => uuid("id").primaryKey().defaultRandom();

/**
 * `created_at` / `updated_at`.
 *
 * `timestamptz`, never `timestamp`: collectors write from phones on IST, the
 * platform runs in UTC, and the hotspot map groups by local day. Storing a wall
 * clock without a zone makes that impossible to recover.
 */
export const timestamps = () => ({
  createdAt: timestamp("created_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date()),
});

/**
 * Money, in **paise**, as `bigint`.
 *
 * Never a float: ₹1,13,050.00 and 113050.00000001 must be the same number. Never
 * `numeric` either — `bigint` with `mode: "number"` keeps integer arithmetic in
 * TypeScript, where every rupee figure in the app is already computed. The largest
 * value here is a few crore, so the range is never in question.
 */
export const money = (name: string) => bigint(name, { mode: "number" });

/** Always INR today; a column so a second currency is not a migration of every table. */
export const currency = () =>
  text("currency").default("INR").notNull();

/**
 * Mass, in **grams**, as `numeric(12,2)`.
 *
 * Grams are the unit the fixtures speak (a motherboard is 240 g) and `numeric`
 * keeps 0.25 g exact while still allowing sums and averages in SQL. This is the
 * only non-integer quantity in the schema.
 */
export const massGrams = (name: string) =>
  numeric(name, { precision: 12, scale: 2 });

/** A model or gatekeeper score in [0, 1]. Three decimals is the model's own precision. */
export const confidence = (name: string) =>
  numeric(name, { precision: 4, scale: 3 });

/** A share of 100, e.g. a recycler's utilisation or a rate card's recovery share. */
export const percent = (name: string) =>
  numeric(name, { precision: 5, scale: 2 });
